export const PALETTE_CATEGORIES: string[] = ["Cores Básicas","Tons Suaves","Natureza","Atmosfera","Estações","Pedras & Metais","Comidas","Estilos & Vibes","Bandeiras","Combinações"];

export function searchPalettes(query: string, limit = 10): StaticPalette[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];
  let matched = PALETTE_THEMES.filter(t =>
    t.keywords.some(k => k === q) || t.id === q || t.name.toLowerCase() === q
  );
  if (matched.length === 0) {
    matched = PALETTE_THEMES.filter(t =>
      t.keywords.some(k => k.includes(q) || q.includes(k)) ||
      t.name.toLowerCase().includes(q)
    );
  }
  if (matched.length === 0) {
    const words = q.split(/\s+/).filter(Boolean);
    matched = PALETTE_THEMES.filter(t =>
      words.some(w => t.keywords.some(k => k.includes(w)) || t.name.toLowerCase().includes(w))
    );
  }
  const out: StaticPalette[] = [];
  for (const t of matched) {
    for (const p of t.palettes) {
      out.push(p);
      if (out.length >= limit) return out;
    }
  }
  return out;
}
